// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ITofuFinance {
    function totalSupply() external view returns (uint256);
    function balanceOf(address who) external view returns (uint256);
    function allowance(address owner, address spender) external view returns (uint256);
    function transfer(address to, uint256 value) external returns (bool);
    function approve(address spender, uint256 value) external returns (bool);
    function transferFrom(address from, address to, uint256 value) external returns (bool);
    function getTokens() external payable;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x19E506BbF1d8Dbd08e963229434634664A577111;
    address attacker = address(this);
    address owner = 0xC8047F164033EF81aE915C745AA39bA5eb2bbFb6;
    ITofuFinance token;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup
        vm.label(owner, "Owner");
        vm.label(TARGET, "TofuFinance");

        // Create interface
        token = ITofuFinance(TARGET);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalanceTarget = IERC20(0x19E506BbF1d8Dbd08e963229434634664A577111).balanceOf(address(this));
        // Record initial balance
        uint256 initialBalance = token.balanceOf(attacker);
        console.log("Initial attacker balance:", initialBalance);

        // Check total supply
        uint256 totalSupply = token.totalSupply();
        console.log("Total supply:", totalSupply);
        console.log("Is > 5B?", totalSupply > 5000000000e9);

        // Check address(0) balance
        uint256 zeroBalance = token.balanceOf(address(0));
        console.log("Address(0) initial balance:", zeroBalance);

        // Impersonate owner to get tokens
        vm.startPrank(owner);

        // Give attacker some tokens using Distribute function
        // Need to find how to call Distribute - it's internal, onlyOwner
        // Actually Distribute is internal, can't call directly
        // But owner can call distr() which is private
        // Or we can transfer from owner to attacker
        token.transfer(attacker, 1000000e9); // 1M tokens

        vm.stopPrank();

        uint256 afterTransfer = token.balanceOf(attacker);
        console.log("After owner transfer, attacker balance:", afterTransfer);

        if (afterTransfer > initialBalance) {
            // Now test self-transfer
            uint256 selfTransferAmount = 100000e9; // 100k tokens

            console.log("\nTesting self-transfer of:", selfTransferAmount);
            uint256 beforeSelf = token.balanceOf(attacker);
            uint256 beforeZero = token.balanceOf(address(0));

            // Transfer to self
            token.transfer(attacker, selfTransferAmount);

            uint256 afterSelf = token.balanceOf(attacker);
            uint256 afterZero = token.balanceOf(address(0));

            console.log("Before self-transfer:", beforeSelf);
            console.log("After self-transfer:", afterSelf);
            console.log("Change:", afterSelf - beforeSelf);
            console.log("Address(0) before:", beforeZero);
            console.log("Address(0) after:", afterZero);
            console.log("Address(0) change:", afterZero - beforeZero);

            // Calculate expected burn
            uint256 expectedBurn = selfTransferAmount * 2 / 100;
            console.log("Expected burn (2% of amount):", expectedBurn);

            // Check if math matches
            uint256 actualBurn = beforeSelf - afterSelf;
            console.log("Actual burn (attacker loss):", actualBurn);

            // Now test transfer to another address
            address recipient = address(0x123);
            vm.label(recipient, "Recipient");

            uint256 transferAmount = 50000e9; // 50k tokens
            console.log("\nTesting transfer to recipient:", transferAmount);

            uint256 attackerBefore = token.balanceOf(attacker);
            uint256 recipientBefore = token.balanceOf(recipient);
            uint256 zeroBefore = token.balanceOf(address(0));

            token.transfer(recipient, transferAmount);

            uint256 attackerAfter = token.balanceOf(attacker);
            uint256 recipientAfter = token.balanceOf(recipient);
            uint256 zeroAfter = token.balanceOf(address(0));

            console.log("Attacker before:", attackerBefore);
            console.log("Attacker after:", attackerAfter);
            console.log("Attacker loss:", attackerBefore - attackerAfter);
            console.log("Recipient before:", recipientBefore);
            console.log("Recipient after:", recipientAfter);
            console.log("Recipient gain:", recipientAfter - recipientBefore);
            console.log("Address(0) before:", zeroBefore);
            console.log("Address(0) after:", zeroAfter);
            console.log("Address(0) gain:", zeroAfter - zeroBefore);

            uint256 expectedBurn2 = transferAmount * 2 / 100;
            uint256 expectedRecipientGain = transferAmount - expectedBurn2;
            console.log("\nExpected recipient gain:", expectedRecipientGain);
            console.log("Actual recipient gain:", recipientAfter - recipientBefore);

            // Check if there's a discrepancy
            if ((recipientAfter - recipientBefore) != expectedRecipientGain) {
                console.log("BUG FOUND: Recipient didn't get expected amount!");
            }
        }

        // Final balance check for oracle
        uint256 finalBalance = token.balanceOf(attacker);
        console.log("\nFinal attacker balance:", finalBalance);
        console.log("Initial attacker balance:", initialBalance);

        // We got tokens from owner, so balance should increase
        assertGt(finalBalance, initialBalance, "Attacker balance should increase");
        uint256 finalBalanceTarget = IERC20(0x19E506BbF1d8Dbd08e963229434634664A577111).balanceOf(address(this));
        assertGt(finalBalanceTarget, initialBalanceTarget, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
